import {questions} from './data.js';import {answer,gradeNumeric} from './core.js';import {updateReview} from './review.js';import {recordEvent,gradeShort} from './adaptive.js';import {mathFamilies} from './math-reference.js';
const mathType={l3q0:'delay','extra-q9':'delay','extra-q10':'pipeline','extra-q11':'queue','extra-q12':'intensity','extra-q13':'throughput','extra-q30':'object-count','extra-q31':'http','extra-q34':'checksum','extra-q35':'ascii',l19q0:'tcpAck','extra-q47':'tcpAck','extra-q44':'tcpWindow','extra-q45':'tcpWindow',l21q1:'subnet','l22q0':'subnet','l22q1':'subnet','extra-q50':'subnet','extra-q51':'subnet','extra-q52':'subnet','extra-q53':'allocation','extra-q55':'ip-length','extra-q56':'ip-length','extra-q62':'routing'};
const byId=new Map(questions.map(q=>[q.id,q]));
const shuffled=(a,rng)=>{let b=[...a];for(let i=b.length-1;i>0;i--){let j=Math.floor(rng()*(i+1));[b[i],b[j]]=[b[j],b[i]]}return b};
export const examFamily=q=>q.worked?'math:'+(q.mathFamily||mathType[q.id]||mathFamilies.find(f=>f.qid===q.id)?.id||q.lesson):q.familyId;
export function buildExam({chapter=-1,count=20,minutes=20,level='mixed',now=Date.now(),rng=Math.random}={}){if(![-1,0,1,2,3].includes(chapter)||!Number.isInteger(count)||count<4||count>40||!Number.isInteger(minutes)||minutes<0||minutes>180)throw Error('Chọn 4–40 câu, thời gian 0–180 phút.');let pool=shuffled(questions.filter(q=>(chapter<0||q.ch===chapter)&&(level==='foundation'?q.level<=2:level==='advanced'?q.level>=3:true)),rng),selected=[],families=new Set(),chs=chapter<0?[0,1,2,3]:[chapter];for(let i=0;i<count;i++){let ch=chs[i%chs.length],lv=[1,2,3,4][Math.floor(i/chs.length)%4];let eligible=pool.filter(q=>!families.has(examFamily(q)));let q=eligible.find(q=>q.ch===ch&&q.level===lv)||eligible.find(q=>q.ch===ch)||eligible[0];if(!q)break;selected.push(q);families.add(examFamily(q))}if(!selected.length)throw Error('Không có câu phù hợp.');return {version:1,id:'exam-'+now+'-'+Math.floor(rng()*1e9),chapter,requested:count,minutes,level,started:now,deadline:minutes?now+minutes*60000:null,index:0,submitted:false,items:selected.map(q=>({qid:q.id,format:q.worked?'short':'mcq',order:shuffled([0,1,2,3],rng),choice:null,draft:'',unknown:false,flag:false}))}}
export function examMatrix(exam){return [0,1,2,3].map(ch=>({ch,total:exam.items.filter(c=>byId.get(c.qid).ch===ch).length,levels:[1,2,3,4].map(l=>exam.items.filter(c=>byId.get(c.qid).ch===ch&&byId.get(c.qid).level===l).length)}))}
export function examQuestion(item){return byId.get(item.qid)}
export function gradeExamItem(item){let q=byId.get(item.qid);if(item.unknown)return false;if(item.format==='mcq')return item.choice!==null&&item.order[item.choice]===q.correct;let g=gradeShort(item.draft,q);if(g.ok)return true;let expected=q.options[q.correct].match(/^\/?(\d+(?:[.,]\d+)?)(?:\s*(?:ms|s|byte|bit|host|Mbps|Kbps|MSS|%))?$/i);return !!expected&&gradeNumeric(item.draft,Number(expected[1].replace(',','.')),{integer:!/[.,]/.test(expected[1]),absTol:/[.,]/.test(expected[1])?.00001:0}).ok}
export function submitExam(state,exam,now=Date.now(),timedOut=false){if(!exam||exam.submitted)return false;let results=exam.items.map(item=>({qid:item.qid,ok:gradeExamItem(item),format:item.format}));Object.assign(exam,{submitted:true,submittedAt:now,timedOut,results});for(let i=0;i<results.length;i++){let result=results[i],q=byId.get(result.qid);answer(state,q.id,result.ok,now);updateReview(state,q.id,result.ok?2:0,result.format,now);recordEvent(state,q,{id:exam.id+':e'+i,runId:exam.id,quality:result.ok?2:0,format:result.format,support:0,novel:q.level>=3,now})}state.exams.push({id:exam.id,date:new Date(now).toISOString(),score:Math.round(results.filter(r=>r.ok).length/results.length*100),kind:'exam-v3',count:results.length,timedOut,matrix:examMatrix(exam)});return true}
export function checkDeadline(state,exam,now=Date.now()){return !!exam&&!exam.submitted&&exam.deadline!==null&&now>=exam.deadline&&submitExam(state,exam,now,true)}
export function cleanExam(raw){if(!raw||raw.version!==1||typeof raw.id!=='string'||raw.id.length>100||!Array.isArray(raw.items)||raw.items.length<1||raw.items.length>40||!Number.isInteger(raw.index)||raw.index<0||raw.index>=raw.items.length||!Number.isFinite(raw.started)||![-1,0,1,2,3].includes(raw.chapter)||raw.deadline!==null&&!Number.isFinite(raw.deadline))return null;let ids=new Set(),items=[];for(let c of raw.items){if(!byId.has(c.qid)||ids.has(c.qid)||!['mcq','short'].includes(c.format)||!Array.isArray(c.order)||c.order.length!==4||[...c.order].sort().join('')!=='0123'||c.choice!==null&&(!Number.isInteger(c.choice)||c.choice<0||c.choice>3))return null;ids.add(c.qid);items.push({qid:c.qid,format:c.format,order:[...c.order],choice:c.choice,draft:typeof c.draft==='string'?c.draft.slice(0,1000):'',unknown:!!c.unknown,flag:!!c.flag})}let e={version:1,id:raw.id,chapter:raw.chapter,requested:Math.min(40,Number(raw.requested)||items.length),minutes:Math.min(180,Math.max(0,Number(raw.minutes)||0)),level:['mixed','foundation','advanced'].includes(raw.level)?raw.level:'mixed',started:raw.started,deadline:raw.deadline,index:raw.index,submitted:raw.submitted===true,items};if(e.submitted){e.submittedAt=Number(raw.submittedAt)||raw.started;e.timedOut=!!raw.timedOut;e.results=items.map(item=>({qid:item.qid,ok:gradeExamItem(item),format:item.format}))}return e}
